        batcher.addCylinder(cx + 0.04, baseH + chamberH - 0.26, 0.05, 0.012, 0.012, 0.32, 8, 'y', 'chrome', 'detail');
        batcher.addCone(cx + 0.04, baseH + chamberH - 0.44, 0.05, 0.055, 0.08, 6, 'secondary', 'detail');
