    locationContext: 'interior',
    environmentTags: ['arcade', 'retro_arcade', 'modern_arcade', 'bowling_alley', 'gaming_lounge', 'residential_game_room'],
    tags: ['stool', 'seating', 'booth', 'party_table', 'lockers', 'stanchion', 'queue'],
